    stroke  = { !this.primary && this.theme.buttonBorder != null ? stroke(1, this.theme.buttonBorder) : null },

    run: View [ height = 100%, x = center,
        width = { this.contentWidth },
        layout: SimpleLayout [ axis = x, spacing = { classroot.gap } ],

        ico:   IconHost [ kind = { classroot.iconLeft },  ink = { classroot.inkColor } ],
        cap:   TextLabel [ wrap = false, fontWeight = semibold,
            visible = { classroot.label != "" }, text = { classroot.label } ],
        trail: IconHost [ kind = { classroot.rightIcon }, ink = { classroot.inkColor } ]
        ]
    ]

/*
# Switch

A boolean control with a sliding thumb — same value contract as Checkbox (`checked`,
`input` owns the destination), different body language: the thumb **springs**
between its two rest points, so toggling moves rather than jumps.

## checked
Whether the switch is on. Bind it (`checked = { app.muted }`) and override `input`
to own the destination, or leave it and read it back — a `Switch` works standalone
with no wiring.

## input()
Where the value goes. The default writes `checked`; override it and the switch
becomes a delivery mechanism for state you own. `press()` never writes `checked`
directly, so a bound switch never fights its constraint.

## press()
Toggles, by delivering the flipped value through `input`. Called by a click and by
Space/Enter.

## onClick
Fires on click when the switch is enabled. `press()` is the activation path;
prefer overriding `input` if what you want is the value.

## width
A theme with a native switch size says so (`theme.switchWidth`); otherwise 44, the common pill.

## height
A theme with a native switch size says so (`theme.switchHeight`); otherwise 24.

## cornerRadius
Always a pill — half the height, whatever the height is.

## opacity
Disabled dims the whole control — every part alike, never a recolour — to the theme's `disabledOpacity`, or 0.45 when the theme states none: the one place the number lives.

## fill
The track's ladder for a toggle: checked takes the accent; unchecked shows the selected tint while hovered or pressed and the quiet control tint at rest — so the track answers the pointer before the value flips.

## stroke
A hairline in the accent when checked, in the theme's line colour otherwise, so the track keeps an edge on light and dark surfaces alike.
*/



class Switch extends Control [
    width  = { typeof this.theme.switchWidth == "number" ? this.theme.switchWidth : 44 },
    height = { typeof this.theme.switchHeight == "number" ? this.theme.switchHeight : 24 },
    cornerRadius = { this.height / 2 },
    checked: boolean = false,

    input(v: boolean) { this.checked = v },

    press()   { this.input(!this.checked) },
    onClick() { if (!this.disabled) this.press() },

    opacity = { this.disabled ? (typeof this.theme.disabledOpacity == "number" ? this.theme.disabledOpacity : 0.45) : 1 },
    fill    = { this.checked ? this.theme.accent : this.hot || this.down ? this.theme.controlSelected : this.theme.control },
    stroke  = { stroke(1, this.checked ? this.theme.accent : this.theme.line) },

    // the thumb derives from the track: inset 2 normally; a theme may say the
    // unchecked thumb is smaller (Mountain View's 16→24 grow-on-check)

    thumb: View [ cornerRadius = { this.width / 2 },
