    bar: View [ y = 12, height = 4, cornerRadius = 2, fill = { classroot.theme.accent },
        width = { classroot.barStyle() ? Math.max(0, classroot.thumb.x - 5) : 9 + (classroot.width - 18) * classroot.frac } ],
